:root {
  --color-primary: #8b5a5f;
  --color-primary-dark: #5a3a3f;
  --color-accent: #d4a574;
  --color-accent-light: #e8c9a8;
  --color-accent-on-dark: #f5e6d3;
  --color-text: #2c2c2c;
  --color-text-light: #5a5a5a;
  --color-bg: #faf9f7;
  --color-bg-light: #f5f3f0;
  --color-border: #e0d9d0;
  --font-serif: 'Palatino Linotype', 'Book Antiqua', Georgia, serif;
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --spacing-2xl: 4rem;
  --radius: 3px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-serif);
  font-size: 1rem;
  line-height: 1.6;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  margin-bottom: var(--spacing-md);
  font-weight: 400;
}

h1 {
  font-size: clamp(2rem, 6vw, 3.5rem);
  letter-spacing: 0.08em;
  font-variant: small-caps;
}

h2 {
  font-size: clamp(1.75rem, 5vw, 2.5rem);
  letter-spacing: 0.08em;
  font-variant: small-caps;
  color: var(--color-primary);
}

h3 {
  font-size: 1.25rem;
  letter-spacing: 0.05em;
}

p {
  margin-bottom: var(--spacing-md);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  border-bottom: 1px solid currentColor;
  transition: color 0.2s ease;
}

a:hover, a:focus {
  color: var(--color-accent);
}

a:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.logo {
  display: inline-block;
  font-family: var(--font-serif);
  font-size: clamp(1.2rem, 4vw, 1.8rem);
  font-weight: 400;
  font-variant: small-caps;
  letter-spacing: 0.25em;
  color: var(--color-primary-dark);
  border: none;
  border-bottom: 1px solid var(--color-primary-dark);
  padding-bottom: 0.3rem;
  transition: border-color 0.2s ease, color 0.2s ease;
}

.logo:hover, .logo:focus {
  border-bottom-color: var(--color-accent);
  color: var(--color-accent);
}

header {
  background-color: #fff;
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-lg) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

header .container {
  display: flex;
  align-items: center;
  justify-content: center;
}

footer {
  background-color: var(--color-primary-dark);
  color: var(--color-accent-on-dark);
  padding: var(--spacing-2xl) 0;
  margin-top: var(--spacing-2xl);
  text-align: center;
}

footer a {
  color: var(--color-accent-light);
  border-bottom-color: var(--color-accent-light);
}

footer a:hover, footer a:focus {
  color: var(--color-accent);
  border-bottom-color: var(--color-accent);
}

.footer-content {
  font-size: 0.95rem;
  margin-bottom: var(--spacing-md);
}

.copyright {
  font-size: 0.85rem;
  margin-bottom: 0;
  opacity: 0.8;
}

.container {
  max-width: 700px;
  margin: 0 auto;
  padding: 0 var(--spacing-lg);
}

main {
  display: block;
}

section {
  padding: var(--spacing-2xl) 0;
}

/* Hero Section */
.hero {
  background: linear-gradient(135deg, var(--color-bg-light) 0%, #fff 100%);
  text-align: center;
  padding: var(--spacing-2xl) var(--spacing-lg);
}

.hero h1 {
  margin-bottom: var(--spacing-md);
  color: var(--color-primary-dark);
}

.hero .tagline {
  font-size: 1.25rem;
  color: var(--color-text-light);
  font-style: italic;
  margin-bottom: 0;
  letter-spacing: 0.05em;
}

/* Details Section */
.details {
  background-color: #fff;
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.detail-item {
  margin-bottom: var(--spacing-lg);
  padding-bottom: var(--spacing-lg);
  border-bottom: 1px solid var(--color-border);
}

.detail-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
  padding-bottom: 0;
}

.detail-item h3 {
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
}

.detail-item p {
  margin-bottom: 0;
  color: var(--color-text-light);
  font-size: 1.05rem;
}

/* RSVP Form Section */
.rsvp {
  background-color: var(--color-bg-light);
  padding: var(--spacing-2xl) var(--spacing-lg);
}

.rsvp h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

form {
  display: flex;
  flex-direction: column;
}

.form-group {
  margin-bottom: var(--spacing-lg);
  display: flex;
  flex-direction: column;
}

label {
  display: block;
  margin-bottom: var(--spacing-xs);
  font-weight: 500;
  color: var(--color-primary-dark);
  font-size: 0.95rem;
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
select,
textarea {
  padding: var(--spacing-sm);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: #fff;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus,
input[type="number"]:focus,
select:focus,
textarea:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(212, 165, 116, 0.1);
}

input[type="radio"],
input[type="checkbox"] {
  margin-right: var(--spacing-xs);
  cursor: pointer;
  accent-color: var(--color-primary);
}

.radio-group,
.checkbox-group {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-sm);
}

.radio-item,
.checkbox-item {
  display: flex;
  align-items: center;
}

.radio-item label,
.checkbox-item label {
  margin-bottom: 0;
  margin-left: var(--spacing-xs);
  cursor: pointer;
  font-weight: 400;
}

button, input[type="submit"] {
  background-color: var(--color-primary-dark);
  color: #fff;
  border: none;
  padding: var(--spacing-sm) var(--spacing-lg);
  font-size: 1rem;
  border-radius: var(--radius);
  cursor: pointer;
  font-family: var(--font-sans);
  font-weight: 600;
  min-height: 44px;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
  letter-spacing: 0.02em;
}

button:hover, input[type="submit"]:hover {
  background-color: var(--color-accent);
  color: var(--color-primary-dark);
}

button:focus, input[type="submit"]:focus {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, input[type="submit"]:active {
  transform: scale(0.98);
}

/* Mobile Breakpoint */
@media (max-width: 600px) {
  :root {
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 2.5rem;
  }

  h1 {
    font-size: 1.75rem;
  }

  h2 {
    font-size: 1.4rem;
  }

  section {
    padding: var(--spacing-xl) 0;
  }

  .container {
    padding: 0 var(--spacing-md);
  }

  .logo {
    font-size: 1.2rem;
  }

  header {
    padding: var(--spacing-md) 0;
  }

  .hero {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .rsvp {
    padding: var(--spacing-xl) var(--spacing-md);
  }

  .detail-item {
    margin-bottom: var(--spacing-md);
    padding-bottom: var(--spacing-md);
  }
}

/* Desktop Breakpoint */
@media (min-width: 601px) {
  section {
    padding: var(--spacing-2xl) 0;
  }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

